fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    host::display::clear(0x000000);
    let mut i: i32 = 0;
    while i < 64 {
        let x: i32 = hash(i * 2 + 1) % w;
        let speed: i32 = hash(i * 3 + 7) % 3 + 1;
        let y: i32 = (hash(i * 5 + 3) + t * speed) % h;
        let mut c: i32 = 0x606060;
        if speed == 2 { c = 0xa0a0a0; }
        if speed == 3 { c = 0xffffff; }
        host::display::set_pixel(x, y, c);
        i = i + 1;
    }
    host::display::present();
}
